SELECT r.id, r.name, r.visibility, r.internal, r.agent_ref, r.enabled, r.schedule_type, r.timezone, r.timeout_seconds, r.description, r.created_by_user_id, r.conversation_id, r.goal_id, r.model_override, r.user_cred_url, r.start_at, r.end_at, r.cron_expr, r.interval_seconds, r.task_prompt_uri, r.task_prompt, r.next_run_at, r.last_run_at, r.last_status, r.last_error, r.lease_owner, r.lease_until, r.created_at, r.updated_at FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM schedule c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)